#!/usr/bin/env python3
"""Verify and summarize the frozen TRAPPIST-1 subband pilot."""
import hashlib,json
from pathlib import Path
from collections import Counter
from ls6_repaired_screen import validate_checkpoint,seal
from seti_repeater.light_sail import apply_abacad_veto

def main():
    path=Path('config/ls6_trappist1_x_subband_repaired.json');config=json.loads(path.read_text());digest=hashlib.sha256(path.read_bytes()).hexdigest()
    result=json.loads(Path('results_ls6_screen/screen.json').read_text())
    assert result['result_sha256']==seal({k:v for k,v in result.items() if k!='result_sha256'})
    assert result['config_sha256']==digest
    scans=[validate_checkpoint(json.loads(Path('results_ls6_screen',s['label']+'.json').read_text()),s,digest) for s in config['selected_sequence']]
    assert scans==result['scans']
    d=config['medium_resolution_screen'];candidates=apply_abacad_veto(scans,on_threshold=d['on_score_threshold'],off_threshold=d['off_veto_score_threshold'],minimum_frequency_overlap=d['off_veto_frequency_overlap'])
    assert candidates==result['candidates']
    survivors=[c for c in candidates if c['survives_adjacent_off_veto']]
    assert len(survivors)==result['surviving_event_count'] and len(candidates)==result['on_threshold_event_count']
    total=sum(s['source_size_bytes'] for s in scans);on_seconds=sum(s['expected_filterbank_header']['ntime']*s['expected_filterbank_header']['tsamp_s'] for s in config['selected_sequence'] if s['role']=='ON')
    lines=['# LS6 TRAPPIST-1 9.92 GHz subband pilot','',f"Status: **{result['status']}**.",'',f"A sixth distinct stellar system has received a project LS spectrum screen, here as a limited four-scan pilot. The selected archive-labelled TRAPPIST-1 observations from 23 February 2017 cover {d['science_band_mhz'][0]/1000:.6f}–{d['science_band_mhz'][1]/1000:.6f} GHz. Two ON and two OFF scans provide {on_seconds:.3f} seconds of designated ON integration. Total input: {total:,} bytes.",'','| Scan | Role | Retained score ≥6 windows | Score ≥8 windows | Truncated |','|---|---|---:|---:|---|']
    for s in scans:lines.append(f"| {s['label']} | {s['role']} | {len(s['search']['events'])} | {sum(e['score']>=8 for e in s['search']['events'])} | {s['search']['retention_truncated']} |")
    lines+=['',f"**{len(candidates)} ON threshold windows; {len(survivors)} survive the frozen adjacent-OFF veto.** Window counts are not independent signals. No score is a calibrated significance.",'']
    if survivors:
        lines+=['Survivors require separately frozen follow-up, pointing checks and independent data. No HTR values were read and no technosignature is claimed.','', 'A descriptive grouping of the retained windows reveals only two shared time intervals: all end at their scan boundary. This raises a scan-end/baseline concern and does not establish astrophysical pulses. It does not alter the primary veto disposition.','', '| ON | Shared time interval (s) | Requested duration (s) | Retained ON windows |','|---|---:|---:|---:|']
        groups=Counter((c['on_label'],c['event']['time_start_s'],c['event']['time_stop_s'],c['event']['requested_duration_s']) for c in survivors)
        for (label,start,stop,duration),count in sorted(groups.items()):lines.append(f"| {label} | {start:.3f}–{stop:.3f} | {duration:.0f} | {count} |")
        lines+=['', 'The complete frequency windows and scores are retained in results_ls6_screen/screen.json. Both OFF scans have all 64 valid base-frequency bins, so their zero-event counts are not caused by an empty or entirely invalid frequency grid. Inspect scan-end common-mode behavior before promoting any candidate.']
    else:lines+=['No window qualifies for HTR follow-up under the frozen rule. This closes only the four-scan subband pilot. No technosignature is claimed.']
    lines+=['','## Scope','','This is an explicitly amended ABAB pilot, not a six-scan ABACAD search or a full-band survey. A1 is checked against B1; A2 against B1 and B2. The LS1 detector thresholds, clipping, native channel aggregation and spectral widths are unchanged. The initial attempt failed because the inherited 64-second template does not fit these 60.13-second scans. A public technical amendment fixed the duration bank at 4,8,16,32 seconds based only on header length. A1 samples had been accessed before this amendment; fitting-window scores were computed internally but not returned, saved or inspected. This is not an independent held-out rerun. The failed freeze and runner are preserved, and no threshold was retuned.','', 'The 187.5 MHz subband was chosen by metadata proximity to the inherited 10 GHz operational anchor. The other 220 medium subband files remain unopened. All seven NASA default transit epochs were absent; the pilot makes no conjunction-ranking claim. A later geometric analysis must adopt and validate published dynamical ephemerides, such as [Agol et al. (2021)](https://arxiv.org/abs/2010.01074).','', 'Designated ON header coordinates differ from the current stellar catalogue by tens of arcseconds. They do not establish full tracking or beam-centering histories. No calibrated sensitivity, target-origin claim, or general constraint on light sails follows from this limited screen.','','## Other targets checked','','Kepler-446 has two individual medium-resolution products but no dedicated cadence in the scoped lookup. Kepler-732 has a complete six-scan listing, yet its three ON HDF5 positions agree with that listing and differ from NASA by 9.6821–9.6824 arcminutes. Kepler-732 spectra remain unopened. HDF5 coordinates were decoded as decimal RA hours / Dec degrees, separately from SIGPROC packed coordinates.','', 'The initial generic HDF5 preflight attempt failed on a missing HTTP dependency; those error receipts are preserved. The later successful, proxy-aware pointing-only audit is results_ls6_header/pointing_audit.json. Missing dependencies were not interpreted as missing archive data.','', 'TRAPPIST-1 was found under DIAG_TRAPPIST1. The archive target query also returns OFF records; exact labels and unique URLs were used for grouping. Its 224 medium products span 16 scan times and four receiver blocks. The selected pilot uses only four products near 9.92 GHz.','','## Verification and reproduction','','All 144 LS tests passed, including explicit four-scan veto mapping, HDF5 coordinate-unit checks, and reproduction of the oversized-template failure plus the repaired duration-bank success. The older full repository suite was attempted during LS5 but did not produce a complete passing summary; only the completed LS suite is claimed here.','', 'Public prespectral freeze: `5aba35e7aaec5de881f71a05edabff8bed56bfed`; tree `1174bc7eb3a77cbbcffc70451744ca88beced78e`. Initial branch ref verified before starting downloads. Technical amendment `208fa0992f66120e7c0e75e89d82ac022f9f4598` (tree `a1a44bb4754e7019c90c256d87b95646427e705f`) was separately ref-verified before the successful rerun.','',f"Configuration SHA-256: `{digest}`. Result identity: `{result['result_sha256']}`.",'', 'This report generator verifies the sealed result, all checkpoint identities and exact veto reproduction. DATA_MANIFEST_LS6.sha256 retains the complete input-file digests and public URLs. Raw radio files are excluded from commits and deleted after use.','', '```bash',"PYTHONPATH=src:scripts python -m unittest discover -s tests -p 'test_ls*.py' -v",'PYTHONPATH=src:scripts python scripts/ls6_repaired_screen.py config/ls6_trappist1_x_subband_repaired.json','PYTHONPATH=src:scripts python scripts/ls6_result_report.py','```','']
    Path('LS6_TRAPPIST1_RESULT.md').write_text('\n'.join(lines))
    print(json.dumps({'status':result['status'],'on_windows':len(candidates),'survivors':len(survivors),'input_bytes':total,'on_seconds':on_seconds,'identity':result['result_sha256']},indent=2))
if __name__=='__main__':main()
